// (Was src/modules/admin/flowtester/types/index.ts @ 4264eb7 before that repo
// migrated to a flat layout — the old path no longer resolves.)
// Frontend mirrors backend entity shapes so future backend changes propagate
// via a simple type sync, not scattered refactors. There is no codegen: adding a
// field here and on the backend are two edits that must land together.

export type ScenarioCategory = string;

// Built-in categories offered in the dropdown, any free-text category is accepted via typing.
export const SUGGESTED_CATEGORIES: ScenarioCategory[] = [
  'happy_path',
  'negative_path',
  'edge_case',
  'out_of_scope',
  'adversarial',
  'testing'
];

export const TEST_RUN_STATUSES = ['pending', 'running', 'completed', 'failed', 'cancelled'] as const;
export type TestRunStatus = (typeof TEST_RUN_STATUSES)[number];

export const SCENARIO_RESULT_STATUSES = [
  'pass',
  'partial',
  'fail',
  'error',
  'timeout',
  'cancelled',
  'running'
] as const;
export type ScenarioResultStatus = (typeof SCENARIO_RESULT_STATUSES)[number];

/**
 * UI-only superset used for rendering in-progress scenarios before a result
 * row exists. The backend now returns 'running' on a partial scenario result
 * while a call is in flight (transcript grows, verdict is null); 'pending' is
 * still synthesized client-side from the TestRun status for scenarios that
 * have no result row yet.
 *
 * 'interrupted' is likewise client-side: a row still marked 'running' on a run
 * that has already finished. The worker skips its terminal write when it is
 * shutting down, and the cancel sweep only patches rows that existed when it
 * ran, so a scenario started in that window keeps 'running' forever. Rendering
 * it as live would show a spinner on a run that ended weeks ago.
 */
export type DisplayScenarioResultStatus = ScenarioResultStatus | 'pending' | 'interrupted';

export const VERDICT_RESULTS = ['pass', 'partial', 'fail'] as const;
export type VerdictResult = (typeof VERDICT_RESULTS)[number];

export function isValidTestRunStatus(value: string): value is TestRunStatus {
  return (TEST_RUN_STATUSES as readonly string[]).includes(value);
}

export interface AgentCapability {
  blockId: string;
  agentName?: string;
  systemPrompt: string;
  sourceType: 'q-in-connect';
}

export interface CapabilityMap {
  agents: AgentCapability[];
}

export interface FlowPromptBlock {
  blockId: string;
  name: string;
  text: string;
  createdAt: string;
  updatedAt: string;
}

export type PromptEditorPart =
  | { partId: string; type: 'block'; blockId: string }
  | { partId: string; type: 'text'; text: string };

export interface PromptEditorLayout {
  caller: PromptEditorPart[];
  judgement: PromptEditorPart[];
}

export interface PromptBlockReference {
  scenarioId: string;
  scenarioName: string;
  locations: Array<'caller' | 'judgement'>;
}

export interface Flow {
  tenantId: string;
  flowId: string;
  flowName: string;
  phoneNumber: string;
  flowJson?: string;
  capabilityMap?: CapabilityMap;
  promptBlocks?: FlowPromptBlock[];
  connectInstanceId?: string;
  createdAt: string;
  updatedAt: string;
}

export interface Scenario {
  tenantId: string;
  scenarioId: string;
  name: string;
  category: ScenarioCategory;
  callerPrompt: string;
  judgementPrompt: string;
  promptEditorLayout?: PromptEditorLayout;
  flowId?: string;
  createdBy?: string;
  createdAt: string;
  /**
   * Sets this scenario belongs to. Optional here, though the API spec has the
   * backend always send an array: the sets endpoints ship after this UI, so
   * every scenario currently comes back without the field. Read it through
   * {@link scenarioSetIds} rather than dereferencing it.
   */
  setIds?: string[];
}

/**
 * Result of a scenario delete — batch or single, since both go through
 * \`POST /scenarios/bulk-delete\`.
 *
 * \`deleted + failed.length === requested\`, always. An id that was already gone
 * counts as deleted, not failed: the caller asked for it not to exist and it
 * doesn't, so its row leaves the grid and a retried delete still reads as a
 * success. \`notFound\` names those ids and is informational — it is a subset of
 * the deleted ids, not a fourth bucket. \`failed\` is reserved for ids that
 * survived the attempt, so a partial failure can keep them selected instead of
 * silently dropping them from the UI.
 */
export interface BulkDeleteScenariosResult {
  /** Distinct ids the request asked about, after duplicates were collapsed. */
  requested: number;
  /** How many ids are gone from the table now — splice these out. */
  deleted: number;
  /** Ids that are still there because the write was rejected — keep these selected. */
  failed: Array<{ scenarioId: string; reason: string }>;
  /** Subset of the deleted ids that were already gone before the request. Informational. */
  notFound: string[];
}

/**
 * Fixed palette for set chips. The backend stores and returns one of these
 * names, never a hex value, so the colour resolves through design-system tokens
 * (see SET_COLOR_CLASSES in \`scenario-sets.ts\`).
 *
 * All six are cool-hued on purpose — the scenario *category* badges own the
 * green/amber/red end of the palette, and a set's colour must not read as a
 * category.
 */
export const SCENARIO_SET_COLORS = ['indigo', 'violet', 'sky', 'teal', 'fuchsia', 'blue'] as const;
export type ScenarioSetColor = (typeof SCENARIO_SET_COLORS)[number];

export function isScenarioSetColor(value: string): value is ScenarioSetColor {
  return (SCENARIO_SET_COLORS as readonly string[]).includes(value);
}

/** A named collection of scenarios within one flow. Membership is many-to-many. */
export interface ScenarioSet {
  tenantId: string;
  setId: string;
  flowId: string;
  name: string;
  color: ScenarioSetColor;
  description?: string;
  /** Current member count, sent by the backend so the rail paints in one request. */
  scenarioCount: number;
  createdBy?: string;
  createdAt: string;
  updatedAt: string;
}

export interface CreateScenarioSetInput {
  flowId: string;
  name: string;
  color?: ScenarioSetColor;
  description?: string;
  /** Seed the new set with these members, so "new set from selection" is one request. */
  scenarioIds?: string[];
}

export interface UpdateScenarioSetInput {
  name?: string;
  color?: ScenarioSetColor;
  /** \`null\` clears the description; omitting the key leaves it untouched. */
  description?: string | null;
}

/** Bulk membership change. At least one of \`add\` / \`remove\` must be non-empty. */
export interface UpdateMembersInput {
  add?: string[];
  remove?: string[];
}

export interface MembershipResult {
  setId: string;
  added: number;
  removed: number;
  scenarioCount: number;
}

export interface TranscriptTurn {
  speaker: 'caller' | 'agent';
  text: string;
  timestamp: number;
}

export interface FlaggedTurn {
  turnIndex: number;
  speakerText: string;
  issue: string;
}

export interface Verdict {
  result: VerdictResult;
  confidence: number;
  reasoning: string;
  flaggedTurns: FlaggedTurn[];
}

export interface ScenarioResult {
  runId: string;
  scenarioId: string;
  status: ScenarioResultStatus;
  transcript: TranscriptTurn[] | null;
  verdict: Verdict | null;
  /** Why the scenario landed on 'error' (e.g. Nova init blocked by Bedrock content filters). */
  errorReason?: string;
  /** Wall-clock duration of the final call attempt in milliseconds. */
  durationMs?: number;
  /** True when the call hit the engine's overall timeout. */
  timedOut?: boolean;
  /** How many call attempts were made (1, or 2 after a transient-failure retry). */
  callAttempts?: number;
  /** Current worker phase while the scenario result is still running. */
  executionPhase?: 'calling' | 'ending' | 'evaluating';
  manualHangupRequestedAt?: string;
  manualHangupCompletedAt?: string;
  manuallyEnded?: boolean;
  /**
   * True when the run's silence timeout ended this call. Unlike \`timedOut\`, it does not
   * override the verdict: the conversation stopped by itself rather than being cut off, so
   * the judge still grades what was said.
   */
  endedOnSilence?: boolean;
  startedAt?: string;
  completedAt?: string;
}

export interface HangupScenarioCallResponse {
  runId: string;
  scenarioId: string;
  status: 'accepted';
  requestedAt: string;
}

/**
 * A ScenarioResult as the UI renders it, widened to carry the client-side
 * 'pending' placeholder status for scenarios that have no backend result row yet.
 */
export type DisplayResult = Omit<ScenarioResult, 'status'> & { status: DisplayScenarioResultStatus };

/**
 * Per-terminal-status scenario tallies for a run, written by the worker when the run
 * completes. Lets the UI separate agent failures ('fail') from infrastructure problems
 * ('error'/'timeout') instead of lumping them into one bar.
 */
export interface ResultCounts {
  pass: number;
  partial: number;
  fail: number;
  error: number;
  timeout: number;
  cancelled: number;
}

export interface TestRun {
  tenantId: string;
  runId: string;
  /**
   * Optional user-supplied label. Absent on runs created before naming
   * existed and on runs the user chose not to name — never key UI off it
   * (names aren't unique); use \`runId\` as the identifier.
   */
  name?: string;
  flowId: string;
  status: TestRunStatus;
  scenarioIds: string[];
  phoneNumber: string;
  totalScenarios: number;
  completedScenarios: number;
  /** Percentage of *judged* scenarios (pass+partial+fail) that passed. Absent when nothing was judged. */
  passRate?: number;
  /** Scenario tallies by terminal status, written when the run completes. */
  resultCounts?: ResultCounts;
  /** Why the run landed on status 'failed'. */
  failureReason?: string;
  ecsTaskArn?: string;
  startedAt?: string;
  completedAt?: string;
  createdBy?: string;
  createdAt: string;
  /** Set the run was started from, when it was started from one. */
  setId?: string;
  /**
   * The set's name as it was when the run started. Denormalised on purpose:
   * renaming or deleting a set must not rewrite what a past run says it tested.
   */
  setName?: string;
  /**
   * Seconds of conversational silence — neither caller nor agent speaking — after which
   * each of this run's calls hung up. Absent means the run had no silence timeout, which
   * is the default. The operator's preference is remembered in browser storage; this field
   * is the record of what the run actually used.
   */
  silenceTimeoutSeconds?: number;
}

export interface StartTestRunInput {
  flowId: string;
  /** Explicit scenarios to run. Provide this or \`setId\` — not both. */
  scenarioIds?: string[];
  /**
   * Run a whole scenario set. The backend resolves it to the set's members when
   * it accepts the run, and records the set on the run for provenance.
   */
  setId?: string;
  /** Optional label for the run. Blank/whitespace-only is treated as unset by the backend. Max 120 chars. */
  name?: string;
  /**
   * Hang up a call after this many seconds in which neither party speaks. Omit for no
   * silence timeout — there is no companion boolean, and the backend rejects values
   * outside 10-300.
   */
  silenceTimeoutSeconds?: number;
}

export interface CreateFlowInput {
  flowName: string;
  phoneNumber: string;
  flowJson?: string;
  capabilityMap?: CapabilityMap;
  connectInstanceId?: string;
}

export interface UpdateFlowInput {
  flowName?: string;
  phoneNumber?: string;
  flowJson?: string;
  capabilityMap?: CapabilityMap;
  connectInstanceId?: string;
}

export interface CreateScenarioInput {
  flowId?: string;
  name: string;
  category: ScenarioCategory;
  callerPrompt: string;
  judgementPrompt: string;
  promptEditorLayout?: PromptEditorLayout;
  createdBy?: string;
  /** Sets the new scenario joins. Omit or \`[]\` to create it unassigned. */
  setIds?: string[];
}

/** Exported set definition. Sets travel by name — a setId means nothing in another flow. */
export interface ExportedScenarioSet {
  name: string;
  color: ScenarioSetColor;
  description?: string;
}

export interface ScenarioExportFile {
  version: string;
  exportedAt: string;
  /** Present from envelope version 2. Absent in files exported before sets shipped. */
  sets?: ExportedScenarioSet[];
  scenarios: Scenario[];
}

export type ScenarioImportRow = Omit<Scenario, 'scenarioId' | 'setIds'> & {
  scenarioId?: string;
  /** Set names to join, matched case-insensitively; the backend creates any that are missing. */
  setNames?: string[];
};

export interface ImportResult {
  total: number;
  created: number;
  updated: number;
  scenarioIds: string[];
  /** How many sets the import had to create. Absent until the backend supports sets. */
  setsCreated?: number;
}

export interface UpdateScenarioInput {
  name?: string;
  category?: ScenarioCategory;
  callerPrompt?: string;
  judgementPrompt?: string;
  /**
   * Replaces membership outright — \`[]\` removes the scenario from every set.
   * Omit the key to leave membership untouched.
   */
  setIds?: string[];
  promptEditorLayout?: PromptEditorLayout;
}
